-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+	// Se non ci sono ne' writer ne' readers, possiamo acquisire subito
+	if (p->writer == 0 && p->nreaders == 0) {
+		p->writer = esecuzione->id;
+		return;
+	}
+
+	// Altrimenti blocchiamo il processo sulla coda w_writers
+	inserimento_lista(p->w_writers, esecuzione);
+	schedulatore();
 }

 /// Parte C++ della primitiva rw_acq_read()
@@ -1962,12 +1969,43 @@ extern "C" void c_rw_acq_read(natl rw)
 		return;
 	}

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+	// Se non c'e' writer, ci sono posti liberi, e non ci sono scrittori in attesa
+	// (fairness: nuovi lettori non possono passare se ci sono scrittori in attesa)
+	if (p->writer == 0 && p->nreaders < MAX_RW_READERS && p->w_writers == nullptr) {
+		p->readers[p->nreaders] = esecuzione->id;
+		p->nreaders++;
+		return;
+	}
+
+	// Altrimenti blocchiamo il processo sulla coda w_readers
+	inserimento_lista(p->w_readers, esecuzione);
+	schedulatore();
+}
+
+// Helper functions for rw_rel_write and rw_rel_read
+// Sblocca tutti i lettori in attesa che possono essere accolti
+// (fino a MAX_RW_READERS o fino a esaurimento della coda)
+// Nota: inspronti() e schedulatore() devono essere chiamati dal chiamante
+static void sblocca_lettori(des_rw* p)
+{
+	while (p->nreaders < MAX_RW_READERS && p->w_readers != nullptr) {
+		des_proc* lettore = rimozione_lista(p->w_readers);
+		p->readers[p->nreaders] = lettore->id;
+		p->nreaders++;
+		inserimento_lista(pronti, lettore);
+	}
 }

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+// Sblocca un solo scrittore in attesa (se presente)
+// Nota: inspronti() e schedulatore() devono essere chiamati dal chiamante
+static void sblocca_scrittore(des_rw* p)
+{
+	if (p->w_writers != nullptr) {
+		des_proc* scrittore = rimozione_lista(p->w_writers);
+		p->writer = scrittore->id;
+		inserimento_lista(pronti, scrittore);
+	}
+}


 /// Parte C++ della primitiva rw_rel_write()
@@ -1987,8 +2025,23 @@ extern "C" void c_rw_rel_write(natl rw)
 		return;
 	}

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+	// Rimuoviamo il writer
+	p->writer = 0;
+
+	// Prepariamo la preemption: mettiamo il processo corrente in coda pronti
+	inspronti();
+
+	// Fairness: al rilascio dello scrittore, diamo precedenza ai lettori
+	// Cerchiamo prima di sbloccare i lettori in attesa
+	sblocca_lettori(p);
+
+	// Se non ci sono lettori da sbloccare, sblocchiamo eventualmente uno scrittore
+	if (p->w_readers == nullptr && p->w_writers != nullptr) {
+		sblocca_scrittore(p);
+	}
+
+	// Potrebbero essere stati aggiunti nuovi processi a pronti
+	schedulatore();
 }

 /// Parte C++ della primitiva rw_rel_read()
@@ -2009,8 +2062,29 @@ extern "C" void c_rw_rel_read(natl rw)
 		return;
 	}

-// ( SOLUZIONE 2026-01-28
-//   SOLUZIONE 2026-01-28 )
+	// Rimuoviamo il lettore dall'array
+	p->readers[pos] = 0;
+	p->nreaders--;
+	// Compattiamo l'array (spostiamo l'ultimo lettore nella posizione libera)
+	if (pos != p->nreaders) {
+		p->readers[pos] = p->readers[p->nreaders];
+		p->readers[p->nreaders] = 0;
+	}
+
+	// Prepariamo la preemption: mettiamo il processo corrente in coda pronti
+	inspronti();
+
+	// Fairness: al rilascio del lettore, diamo precedenza agli scrittori
+	if (p->w_writers != nullptr) {
+		// Se ci sono scrittori in attesa, ne sblocchiamo uno
+		sblocca_scrittore(p);
+	} else {
+		// Se non ci sono scrittori in attesa, sblocchiamo eventuali lettori
+		sblocca_lettori(p);
+	}
+
+	// Potrebbero essere stati aggiunti nuovi processi a pronti
+	schedulatore();
 }
 // ESAME 2026-01-28 )

